data class JobDto(val id:String?,val title:String?,val status:String?)
sealed interface JobStatus { data object Open:JobStatus; data object Closed:JobStatus; data class Unknown(val raw:String?):JobStatus }
data class Job(val id:String,val title:String,val status:JobStatus)
fun JobDto.toDomain():Result<Job> = runCatching {
 val stableId=requireNotNull(id?.takeIf(String::isNotBlank))
 Job(stableId,title?.trim().orEmpty(),when(status){
  "OPEN"->JobStatus.Open; "CLOSED"->JobStatus.Closed; else->JobStatus.Unknown(status)
 })
}
